I_DOC = '<path d="M6 2h9l5 5v15H6z"/><path d="M14 2v6h6M9 13h6M9 17h6"/>'
I_DL = '<path d="M12 3v12M7 10l5 5 5-5M5 21h14"/>'
I_SCALE = '<path d="M12 3v18M5 21h14M6 7h12M6 7l-3 6a3 3 0 0 0 6 0zM18 7l-3 6a3 3 0 0 0 6 0z"/>'
I_OK = '<path d="M5 12l5 5L20 7"/>'

def body(sub, i, up, href, fmt):
    L = next(l for l in LAWS if l["sub"] == sub)
    meta = (f'<dl class="lwmeta"><div><dt>{X["num"][i]}</dt><dd>{L["num"]}</dd></div><div><dt>{X["date"][i]}</dt><dd>{fmt(L["date"], i)}</dd></div>'
            f'<div><dt>{X["reg"][i]}</dt><dd>{L["reg"]}</dd></div></dl>')
    hero = (f'<p class="rsback"><a href="{href("documents/")}">← {X["back"][i]}</a></p>'
            f'<div class="lwhero"><span class="lwic">{_svg(I_SCALE, 34)}</span><div><span class="lwkind">{L["kind"][i]}</span><h2>«{L["title"][i]}»</h2>{meta}'
            f'<div class="btns">' + (f'<a class="btn p" href="{L["pdfs"][i]}" rel="noopener">{_svg(I_DL, 18)} {X["dl"][i]}</a>' if L["pdfs"] else '') + f'<a class="btn {"s" if L["pdfs"] else "p"}" href="{L["lex"][i]}" rel="noopener">{X["lex"][i]} →</a></div></div></div>')
    goal = f'<div class="card lwgoal"><h3>{X["goal_h"][i]}</h3><p>{L["goal"][i]}</p></div>'
    pts = "".join(f'<li style="--ac:{c}"><span class="lwpi">{_svg(IC[k], 24)}</span><div><h3><em>{n}</em>{h[i]}</h3><p>{t[i]}</p></div></li>' for n, (k, c, h, t) in enumerate(L["points"], 1))
    forus = "".join(f'<li><span>{_svg(I_OK, 14, 3)}</span>{f[i]}</li>' for f in L["forus"])
    annex = "".join(f'<li><b>{n}</b>{a[i]}</li>' for n, a in enumerate(L["annex"], 1))
    doc = (f'<div class="card cndoc"><a class="cnthumb" href="{L["lex"][i]}" target="_blank" rel="noopener"><img src="{up}{L["thumb"]}" alt="{L["short"][i]}" width="620" height="877"><span>PDF</span></a>'
           f'<div><span class="cntag">{_svg(I_DOC, 16)} {X["doc_h"][i]} · {X["pages"][i].format(n=L["pages"])}</span><h3>{L["kind"][i]} {L["num"]}</h3>'
           f'<div class="btns">' + (f'<a class="btn p" href="{L["pdfs"][i]}" rel="noopener">{_svg(I_DL, 18)} {X["dl"][i]}</a>' if L["pdfs"] else '') + f'<a class="btn s" href="{L["lex"][i]}" target="_blank" rel="noopener">{X["lex"][i]} →</a></div></div></div>')
    tb = ""
    if L.get("table"):
        T = L["table"]
        tb = (f'<div class="card lwtable"><h3>{T["h"][i]}</h3><div class="lwtw"><table><thead><tr>' + "".join(f'<th>{c}</th>' for c in T["cols"][i]) + '</tr></thead><tbody>'
              + "".join(f'<tr><td>{a}</td><td><b>{b}</b></td><td><span class="lwbig">{c}</span></td></tr>' for a, b, c in T["rows"]) + f'</tbody></table></div><p>{T["note"][i]}</p></div>')
    return (f'{hero}{goal}<h2>{X["main_h"][i]}</h2><ol class="lwpts">{pts}</ol>{tb}'
            f'<div class="card lwforus"><h2>{X["forus_h"][i]}</h2><ul>{forus}</ul></div>'
            f'<div class="actwo"><div class="card lwannex"><h3>{X["annex_h"][i]}</h3><ol>{annex}</ol></div>{doc}</div><p class="note">{X["note"][i]}</p>')

def doc_cards(i, up):
    return (f'<h2 style="margin-top:34px">{X["norm_h"][i]}</h2><p>{X["norm_p"][i]}</p><div class="lwcards">' + "".join(
        f'<a class="card lwcard" href="{up}{["", "en/", "uz/", "ru/"][i]}{L["sub"]}"><span class="lwic">{_svg(I_SCALE, 26)}</span><div><small>{L["kind"][i]} · {L["num"]}</small><b>«{L["title"][i]}»</b>'
        f'<span>{X["read"][i]} →</span></div></a>' for L in LAWS) + '</div>')
def names(i):
    return {L["sub"]: L["short"][i] for L in LAWS}
def descs():
    return {L["sub"]: tuple(f'{L["kind"][k]} {L["num"]}: {L["title"][k]}. ' + X["main_h"][k] + "." for k in range(4)) for L in LAWS}
